class METInventItemPriceActivationJob extends RunBaseBatch implements BatchRetryable
{
    FromDate                      fromDate;
    ItemId                        itemId;

    DialogField                   dlgFromDate;
    DialogField                   dlgItemId;

    QueryRun       queryRun;

    BatchHeader    currentBatchHeader;
    guid           currentSessionId;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        fromDate,
        itemId
    #endmacro

}

Method.Source:
public Object dialog()
{
    DialogRunbase       dialog = super();
    ;
    dlgFromDate = dialog.addFieldValue(extendedTypeStr(FromDate), fromDate, "@SYS5209", "@SYS5209");
    dlgItemId   = dialog.addFieldValue(extendedTypeStr(ItemId), itemId);

    return dialog;
}

public boolean getFromDialog()
{
    ;
    fromDate = dlgFromDate.value();
    itemId   = dlgItemId.value();

    SysQuery::findOrCreateRange(
        queryRun.query().dataSourceTable(tableNum(GUPItemBasePrice)),
        fieldNum(GUPItemBasePrice, FromDate))
        .value(!fromDate ? SysQuery::range(dateNull(), systemDateGet()) : queryValue(fromDate));

    SysQuery::findOrCreateRange(
        queryRun.query().dataSourceTable(tableNum(GUPItemBasePrice)),
        fieldNum(GUPItemBasePrice, ItemId))
        .value(itemId ? queryValue(itemId) : SysQuery::valueUnlimited());

    return super();
}

public void initQuery()
{
    Query                   query = new Query();
    QueryBuildDataSource    qbds = query.addDataSource(tablenum(GUPItemBasePrice));
    QueryBuildRange         priceTypeRange, priceActivationStatusRange;
    ;

    priceTypeRange = SysQuery::findOrCreateRange(qbds, fieldnum(GUPItemBasePrice, PriceType));
    priceTypeRange.status(RangeStatus::Locked);
    priceTypeRange.value(queryValue(GUPBasePriceType::BasePriceInventoryCost));

    priceActivationStatusRange = SysQuery::findOrCreateRange(qbds, fieldnum(GUPItemBasePrice, METItemPriceActivationStatus));
    priceActivationStatusRange.status(RangeStatus::Locked);
    priceActivationStatusRange.value(queryValue(METItemPriceActivationStatus::None));

    QueryBuildRange toDateRange = SysQuery::findOrCreateRange(qbds, fieldnum(GUPItemBasePrice, ToDate));
    toDateRange.status(RangeStatus::Locked);
    toDateRange.value(SysQuery::valueUnlimited()); // refreshed at runtime to exclude expired records

    SysQuery::findOrCreateRange(qbds, fieldnum(GUPItemBasePrice, ItemId));

    queryRun = new QueryRun(query);
}

public boolean unpack(container _packedClass)
{
    Version    version = RunBase::getVersion(_packedClass);
    container  queryCon;
    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList, queryCon] = _packedClass;
            if (SysQuery::isPackedOk(queryCon))
            {
                queryRun = new QueryRun(queryCon);
            }
            else
            {
                this.initQuery();
            }
            break;
        default:
            return false;
    }
    return true;
}

public void run()
{
    int                                     processedCounter;
    int                                     priceRecordsCount;
    GUPItemBasePrice                        itemBasePrice;
    GUPItemBasePrice                        itemBasePriceUpdate;
    GUPItemBasePrice                        newerBasePriceRecord;
    InventItemPriceSim                      inventItemPriceSim;
    GUPParameters                           gupParameters = GUPParameters::find();
    InventItemPriceActivationTasksBuilder   tasksBuilder;
    List                                    basePriceRecIds;
    TransDate                               jobStartDate = systemDateGet(); // captured before processing to avoid day-boundary issues

    currentSessionId = newGuid();

    this.initCurrentBatchHeader();

    // For scheduled batch the query is unpacked from a previous run; refresh the date range to today
    if (!fromDate)
    {
        SysQuery::findOrCreateRange(
            queryRun.query().dataSourceTable(tableNum(GUPItemBasePrice)),
            fieldNum(GUPItemBasePrice, FromDate))
            .value(SysQuery::range(dateNull(), systemDateGet()));
    }

    // Refresh ToDate range to exclude expired records (open-ended or end date >= today)
    SysQuery::findOrCreateRange(
        queryRun.query().dataSourceTable(tableNum(GUPItemBasePrice)),
        fieldNum(GUPItemBasePrice, ToDate))
        .value(strfmt('((%1 == %2) || (%1 >= %3))',
            fieldStr(GUPItemBasePrice, ToDate),
            date2StrXpp(dateNull()),
            date2StrXpp(systemDateGet())));

    if (this.isInBatch())
    {
        tasksBuilder    = InventItemPriceActivationTasksBuilder::construct()
                            .setPrototype(InventItemPriceActivationTaskActivateSim::construct())
                            .setBundleSize(InventParameters::find().InventItemPriceActivationBundleSize);
        basePriceRecIds = new List(Types::Int64);
    }

    while (queryRun.next())
    {
        itemBasePrice = queryRun.get(tableNum(GUPItemBasePrice));

        // Skip if a newer past-dated record exists for this item+inventdim (activate only the most recent)
        select firstonly RecId from newerBasePriceRecord
            where newerBasePriceRecord.PriceType   == itemBasePrice.PriceType
               && newerBasePriceRecord.ItemId      == itemBasePrice.ItemId
               && newerBasePriceRecord.InventDimId == itemBasePrice.InventDimId
               && newerBasePriceRecord.FromDate    >  itemBasePrice.FromDate
               && newerBasePriceRecord.FromDate    <= systemDateGet();

        if (newerBasePriceRecord.RecId)
        {
            continue;
        }

        ttsbegin;

        itemBasePriceUpdate = GUPItemBasePrice::findByDateRanges(
                                itemBasePrice.ItemId, itemBasePrice.PriceType, itemBasePrice.InventDimId,
                                itemBasePrice.FromDate, itemBasePrice.ToDate, itemBasePrice.OperationGuid, true);

        if (!itemBasePriceUpdate)
        {
            ttsabort;
            continue;
        }

        inventItemPriceSim.clear();
        inventItemPriceSim.ItemId      = itemBasePriceUpdate.ItemId;
        inventItemPriceSim.VersionId   = gupParameters.METCostingVersionId;
        inventItemPriceSim.InventDimId = InventTable::priceInventDimId(itemBasePriceUpdate.ItemId, itemBasePriceUpdate.InventDimId);
        inventItemPriceSim.PriceType   = CostingVersionPriceType::Cost;
        inventItemPriceSim.PriceQty    = 1;
        inventItemPriceSim.PriceUnit   = 1;
        inventItemPriceSim.Markup      = 0;
        inventItemPriceSim.UnitID      = itemBasePriceUpdate.UnitId;
        inventItemPriceSim.Price       = itemBasePriceUpdate.Price;
        inventItemPriceSim.PriceCalcId = itemBasePriceUpdate.PriceCalcId;
        inventItemPriceSim.FromDate    = itemBasePriceUpdate.FromDate;

        if (inventItemPriceSim.validateWrite())
        {
            if (InventItemPriceSim::find(inventItemPriceSim.ItemId, inventItemPriceSim.VersionId,
                                         inventItemPriceSim.FromDate, inventItemPriceSim.PriceType,
                                         inventItemPriceSim.InventDimId))
            {
                info(strfmt("Duplicate cost found and activation skipped Item Number : %1 Cost Price : %2 From Date : %3",
                    inventItemPriceSim.ItemId,
                    inventItemPriceSim.Price,
                    date2StrUsr(inventItemPriceSim.FromDate, DateFlags::FormatAll)));

                itemBasePriceUpdate.METItemPriceActivationStatus = METItemPriceActivationStatus::Skipped;
                itemBasePriceUpdate.update();
            }
            else
            {
                inventItemPriceSim.METGUPItemBasePriceId = itemBasePriceUpdate.RecId;
                inventItemPriceSim.METSessionGuid        = currentSessionId;
                inventItemPriceSim.insert();

                if (this.isInBatch())
                {
                    tasksBuilder.addInventItemPriceSimForActivation(inventItemPriceSim);
                    basePriceRecIds.addEnd(itemBasePriceUpdate.RecId);
                    priceRecordsCount++;
                }
                else
                {
                    METItemPriceActivationStatus activationStatus = METItemPriceActivationStatus::Failed;

                    try
                    {
                        InventItemPriceActivationJob::activateInventItemPriceSimExt(inventItemPriceSim);
                        activationStatus = METItemPriceActivationStatus::Completed;
                    }
                    catch
                    {
                        // activationStatus remains Failed; error already in infolog
                        inventItemPriceSim.delete();
                    }

                    itemBasePriceUpdate.METItemPriceActivationStatus = activationStatus;
                    itemBasePriceUpdate.update();
                }
            }

            processedCounter++;
        }
        else
        {
            warning(strfmt("Cost price creation skipped due to validation failure for Item Number : %1 From Date : %2",
                itemBasePriceUpdate.ItemId,
                date2StrUsr(itemBasePriceUpdate.FromDate, DateFlags::FormatAll)));
            itemBasePriceUpdate.METItemPriceActivationStatus = METItemPriceActivationStatus::Failed;
            itemBasePriceUpdate.update();
            processedCounter++;
        }

        ttscommit;
    }

    if (this.isInBatch() && priceRecordsCount > 0)
    {
        this.scheduleItemPriceActivationTasks(tasksBuilder.getResult(), basePriceRecIds, priceRecordsCount, jobStartDate);
    }

    // For batch mode, costing version dates are updated by the completion task after prices are activated
    if (!this.isInBatch() && gupParameters.METCostingVersionId)
    {
        ttsbegin;
        CostingVersion::updateLastActivation(gupParameters.METCostingVersionId);
        CostingVersion::updateLastUpdated(gupParameters.METCostingVersionId);
        ttscommit;
    }

    info(strfmt(" %1 record(s) processed", processedCounter));
}

private void scheduleItemPriceActivationTasks(
    Enumerator  _taskEnumerator,
    List        _basePriceRecIds,
    int         _scheduled,
    TransDate   _jobStartDate)
{
    ttsbegin;

    GUPParameters gupParams = GUPParameters::find();

    METInventItemPriceActivationTaskComplete metCompletionTask = METInventItemPriceActivationTaskComplete::construct();
    metCompletionTask.parmBasePriceRecIds(_basePriceRecIds);
    metCompletionTask.parmCostingVersionId(gupParams.METCostingVersionId);
    metCompletionTask.parmPricesScheduledCount(_scheduled);
    metCompletionTask.parmJobStartDate(_jobStartDate);
    metCompletionTask.batchInfo().parmRuntimeTask(true);
    metCompletionTask.batchInfo().parmGroupId(currentBatch.GroupId);
    currentBatchHeader.addTask(metCompletionTask);

    while (_taskEnumerator.moveNext())
    {
        InventItemPriceActivationTaskActivateSim task = _taskEnumerator.current();
        task.batchInfo().parmRuntimeTask(true);
        task.batchInfo().parmGroupId(currentBatch.GroupId);
        currentBatchHeader.addTask(task);
        currentBatchHeader.addDependency(metCompletionTask, task, BatchDependencyStatus::FinishedOrError);
    }

    currentBatchHeader.save();

    ttscommit;
}

public static METInventItemPriceActivationJob construct()
{
    return new METInventItemPriceActivationJob();
}

static ClassDescription description()
{
    return "Metcash - Activate future cost price";
}

public static void main(Args _args)
{
    METInventItemPriceActivationJob    runObject = METInventItemPriceActivationJob::construct();
    ;
    if (runObject.prompt())
    {
        runObject.runOperation();
    }
}
